        assertEquals("2,19:39-2,19:39", orig.endSourceRange().toString());

        Range.AttributeRange attributeRange = p.attributes().sourceRange("id");
        assertEquals("2,5:25-2,7:27=2,8:28-2,9:29", attributeRange.toString());

        Document clean = new Cleaner(Safelist.relaxed().addAttributes("p", "id")).clean(orig);
        Element cleanP = clean.expectFirst("p");
        assertEquals("1", cleanP.id());
        Range cleanRange = cleanP.sourceRange();
        assertEquals(origRange, cleanRange);
        assertEquals(p.endSourceRange(), cleanP.endSourceRange());
        assertEquals(attributeRange, cleanP.attributes().sourceRange("id"));
    }

    @ParameterizedTest @ValueSource(booleans = {true, false})
    void cleansCaseSensitiveElements(boolean preserveCase) {
        // https://github.com/jhy/jsoup/issues/2049
        String html = "<svg><feMerge baseFrequency=2><feMergeNode kernelMatrix=1 /><feMergeNode><clipPath /></feMergeNode><feMergeNode />";
        String[] tags = {"svg", "feMerge", "feMergeNode", "clipPath"};
        String[] attrs = {"kernelMatrix", "baseFrequency"};

        if (!preserveCase) {
            tags = Arrays.stream(tags).map(String::toLowerCase).toArray(String[]::new);
            attrs = Arrays.stream(attrs).map(String::toLowerCase).toArray(String[]::new);
        }

        Safelist safelist = Safelist.none().addTags(tags).addAttributes(":all", attrs);
        String clean = Jsoup.clean(html, safelist);
        String expected = "<svg>\n" +
            " <feMerge baseFrequency=\"2\">\n" +
            "  <feMergeNode kernelMatrix=\"1\" />\n" +
            "  <feMergeNode>\n" +
            "   <clipPath />\n" +
            "  </feMergeNode>\n" +
            "  <feMergeNode />\n" +
            " </feMerge>\n" +
            "</svg>";
        assertEquals(expected, clean);
    }

    @Test void nofollowOnlyOnExternalLinks() {
        // We want to add nofollow to external links, but not to for relative links or those on the same site
        String html = "<a href='http://external.com/'>One</a> <a href='/relative/'>Two</a> <a href='../other/'>Three</a> <a href='http://example.com/bar'>Four</a>";

        Safelist basic = Safelist.basic().preserveRelativeLinks(true);
        String clean = Jsoup.clean(html, "http://example.com/", basic);
        assertEquals("<a href=\"http://external.com/\" rel=\"nofollow\">One</a> <a href=\"/relative/\">Two</a> <a href=\"../other/\">Three</a> <a href=\"http://example.com/bar\">Four</a>", clean);

        // If we don't pass in a base URI, still want to preserve the relative links.
        String clean2 = Jsoup.clean(html, basic);
        assertEquals("<a href=\"http://external.com/\" rel=\"nofollow\">One</a> <a href=\"/relative/\">Two</a> <a href=\"../other/\">Three</a> <a href=\"http://example.com/bar\" rel=\"nofollow\">Four</a>", clean2);
        // Four gets nofollowed because we didn't specify the base URI, so must assume it is external

        // Want it to be valid with relative links (and no base uri required / provided):
        assertTrue(Jsoup.isValid(html, basic));

        // test that it works in safelist.relaxed as well, which doesn't by default have rel=nofollow
        Safelist relaxed = Safelist.relaxed().preserveRelativeLinks(true).addEnforcedAttribute("a", "rel", "nofollow");
        String clean3 = Jsoup.clean(html, "http://example.com/", relaxed);
        assertEquals("<a href=\"http://external.com/\" rel=\"nofollow\">One</a> <a href=\"/relative/\">Two</a> <a href=\"../other/\">Three</a> <a href=\"http://example.com/bar\">Four</a>", clean3);
        assertTrue(Jsoup.isValid(html, relaxed));

        String clean4 = Jsoup.clean(html, relaxed);
        assertEquals("<a href=\"http://external.com/\" rel=\"nofollow\">One</a> <a href=\"/relative/\">Two</a> <a href=\"../other/\">Three</a> <a href=\"http://example.com/bar\" rel=\"nofollow\">Four</a>", clean4);
    }

    @Test void nofollowComparesLinkHosts() {
        Safelist basic = Safelist.basic();

        // A hostname that extends the base hostname is still external
        String external = Jsoup.clean("<a href='https://example.com.test/path'>Link</a>", "https://example.com", basic);
        assertEquals("<a href=\"https://example.com.test/path\" rel=\"nofollow\">Link</a>", external);

        // The base URI path, scheme, and port do not make another URL on the same host external
        String internal = Jsoup.clean("<a href='http://example.com:8080/other'>Link</a>", "https://example.com:8443/path/page", basic);
        assertEquals("<a href=\"http://example.com:8080/other\">Link</a>", internal);
    }

    @Test void canonicalizesEnforcedAttributes() {
        Document customDirty = Jsoup.parse("<a REL='external'>One</a>", "",
            Parser.htmlParser().settings(ParseSettings.preserveCase));
        Cleaner customCleaner = new Cleaner(Safelist.none()
            .addTags("a")
            .addEnforcedAttribute("a", "rel", "external"));
        assertEquals("<a rel=\"external\">One</a>", customCleaner.clean(customDirty).body().html());
    }

    @Test void canonicalizesNofollowEnforcedAttribute() {
        Document dirty = Jsoup.parse("<a href='http://external.com/' REL='nofollow'>One</a>", "",
            Parser.htmlParser().settings(ParseSettings.preserveCase));
        Cleaner cleaner = new Cleaner(Safelist.basic());
        assertEquals("<a href=\"http://external.com/\" rel=\"nofollow\">One</a>", cleaner.clean(dirty).body().html());
    }

    @Test void preservesMatchingSourceNofollowWhenEnforcementSuppressed() {
        Document dirty = Jsoup.parse("<a href='http://example.com/foo' REL='nofollow'>One</a>", "http://example.com/",
            Parser.htmlParser().settings(ParseSettings.preserveCase));
        Cleaner cleaner = new Cleaner(Safelist.basic());
        assertEquals("<a href=\"http://example.com/foo\" REL=\"nofollow\">One</a>", cleaner.clean(dirty).body().html());
    }

    @Test void discardsSvgScriptData() {
        // https://github.com/jhy/jsoup/issues/2320
        Safelist svgOk = Safelist.none().addTags("svg");
        String cleaned = Jsoup.clean("<svg><script> a < b </script></svg>", svgOk);
        assertEquals("<svg></svg>", cleaned);
    }

    @Test void canSupplyConfiguredTagset() {
        // https://github.com/jhy/jsoup/issues/2326

        // by default, iframe is data
        String input = "<iframe>content is <data></iframe>";
        Safelist safelist = Safelist.relaxed().addTags("iframe");
        String clean = Jsoup.clean(input, safelist);
        assertEquals("<iframe>content is <data></iframe>", clean);

        Document doc = Jsoup.parse(input);
        assertEquals("", doc.text()); // data is not text

        // can change to text
        TagSet tags = TagSet.Html();
        Tag iframe = tags.valueOf("iframe", Parser.NamespaceHtml);
        iframe.clear(Tag.Data).set(Tag.RcData);
        Document doc2 = Jsoup.parse(input, Parser.htmlParser().tagSet(tags));
        assertEquals("content is <data>", doc2.text());
        assertEquals("<iframe>content is &lt;data&gt;</iframe>", doc2.body().html());

        // text nodes are escaped
        assertEquals("<iframe>content is &lt;data&gt;</iframe>", doc2.body().html());

        // can use cleaner with updated tagset
        Cleaner cleaner = new Cleaner(Safelist.relaxed());
        String clean2 = cleaner.clean(doc2).body().html();
        assertEquals("content is &lt;data&gt;", clean2);
    }

    @Test void malformedRawtext() {
        Safelist policy = Safelist.basic().addTags("style");
        String input = "<style></t</style><img>";
        assertEquals("<style></t</style>", Jsoup.clean(input, policy));
    }

    // Cleaning must not invent whitespace or characters, and cleaning its own output again must be a fixed point.

    @Test void cleanIsIdempotentWithTextBetweenBlocks() {
        // inline text directly between block siblings is pretty-printed with a separating newline; a second clean
        // must not turn that newline into a leading space
        Safelist safelist = Safelist.none().addTags("p", "b");
        String html = "<p>One</p>Two <b>three</b><p>Four</p>";

        String clean1 = Jsoup.clean(html, safelist);
        assertEquals("<p>One</p>\nTwo <b>three</b>\n<p>Four</p>", clean1);

        String clean2 = Jsoup.clean(clean1, safelist);
        assertEquals(clean1, clean2);
        assertEquals(clean2, Jsoup.clean(clean2, safelist));
    }

    @Test void cleanIsIdempotentAfterHoistingRejectedWrapper() {
        // the rejected wrapper is removed and its safe children hoisted; the trailing loose text must stay stable
        Safelist safelist = Safelist.none().addTags("p");
        String html = "<p>a</p><font>x</font> <p>b</p>";

        String clean1 = Jsoup.clean(html, safelist);
        String clean2 = Jsoup.clean(clean1, safelist);
        assertEquals(clean1, clean2);
        assertFalse(clean2.contains("\n x"), "no leading space may be introduced in front of hoisted text");
    }

    @Test void cleanIsIdempotentWhenWhitespaceFlanksRejectedNode() {
        // the rejected node sat between two whitespace runs; after hoisting they must behave like one merged run
        Safelist safelist = Safelist.none();
        String html = "<p>x</p> \n <script>y</script> <p>z</p>";

        String clean1 = Jsoup.clean(html, safelist);
        String clean2 = Jsoup.clean(clean1, safelist);
        assertEquals(clean1, clean2);
        assertEquals("x z", clean2);
    }

    @Test void droppedUnsafeHrefStillGetsEnforcedNofollow() {
        // a smuggled unsafe href is dropped, but the enforced rel=nofollow must still be applied and stay stable
        Safelist safelist = Safelist.basic();
        String html = "<a href='java%73cript:1'>x</a>";

        String clean1 = Jsoup.clean(html, "https://example.com/a/b/", safelist);
        assertEquals("<a rel=\"nofollow\">x</a>", clean1);
        assertEquals(clean1, Jsoup.clean(clean1, "https://example.com/a/b/", safelist));
    }

    @Test void rejectedWrapperHoistsSafeSubtreeInOrder() {
        Safelist safelist = Safelist.none().addTags("p", "b");
        assertEquals("foo <b>bar</b> baz", Jsoup.clean("<font>foo <b>bar</b> baz</font>", safelist));
        assertEquals("<b>x</b>", Jsoup.clean("<font><center><b>x</b></center></font>", safelist));
        assertEquals("<p>safe</p>", Jsoup.clean("<custom><p>safe</p></custom>", safelist));
    }

    @Test void safeTextKeptWhenWrappedInDanger() {
        // script contents/events never become executable markup, but safe siblings/text are retained with clear bounds
        Safelist safelist = Safelist.none().addTags("p");
        assertEquals("<p>a</p>\n<p>b</p>", Jsoup.clean("<p>a</p><script>alert(1)</script><p>b</p>", safelist));
        String events = Jsoup.clean("<p onclick='alert(1)'>text</p>", safelist);
        assertEquals("<p>text</p>", events);
        assertFalse(events.toLowerCase().contains("onclick"));
    }

    @Test void preservesWhitespaceAndLiteralsInPreAndTextarea() {
        Safelist safelist = Safelist.none().addTags("pre", "textarea", "code");
        String pre = Jsoup.clean("<pre>  a\n\tb &lt; c  &amp;amp;</pre>", safelist);
        assertEquals("<pre>  a\n\tb &lt; c  &amp;amp;</pre>", pre);
        assertEquals(pre, Jsoup.clean(pre, safelist));

        String textarea = Jsoup.clean("<textarea>a &amp; b\n  c&lt;d</textarea>", safelist);
        assertEquals("<textarea>a &amp; b\n  c&lt;d</textarea>", textarea);
        assertEquals(textarea, Jsoup.clean(textarea, safelist));

        // code keeps consecutive spaces, tabs, and newlines like pre
        String code = Jsoup.clean("<code>x = 1\n  y\tz  &lt;a&gt;</code>", safelist);
        assertEquals("<code>x = 1\n  y\tz  &lt;a&gt;</code>", code);
        assertEquals(code, Jsoup.clean(code, safelist));
    }

    @Test void entitiesAreDecodedOnlyOnce() {
        Safelist safelist = Safelist.none().addTags("p");
        String once = Jsoup.clean("<p>&amp;amp; &lt;img src=x&gt;</p>", safelist);
        assertEquals("<p>&amp;amp; &lt;img src=x&gt;</p>", once);
        assertEquals(once, Jsoup.clean(once, safelist));
    }

    @Test void emptyRejectedAndMalformedInputsAreStable() {
        Safelist safelist = Safelist.none().addTags("p");
        String[] inputs = {"", "   ", "<script>x</script><style>y</style>", "</div></tr><<<>>><p>x", "\0\0\0"};
        for (String input : inputs) {
            String clean1 = Jsoup.clean(input, safelist);
            String clean2 = Jsoup.clean(clean1, safelist);
            assertEquals(clean1, clean2, "re-clean must be stable for input: " + input);
        }
        assertEquals("", Jsoup.clean("", safelist));
        assertEquals("", Jsoup.clean("<script>x</script>", safelist));
    }

    @Test void recleanedOutputReparsesToSameStructure() {
        Safelist safelist = Safelist.none()
            .addTags("p", "b", "i", "h1", "table", "tbody", "tr", "td", "div");
        String html = "<h1>H</h1>text<table><tr><td>x</table>end<div><p>a</p>tail</div>";

        String clean1 = Jsoup.clean(html, safelist);
        String clean2 = Jsoup.clean(clean1, safelist);
        assertEquals(clean1, clean2);

        Document d1 = Jsoup.parseBodyFragment(clean1);
        Document d2 = Jsoup.parseBodyFragment(clean2);
        for (String css : new String[]{"h1", "table", "tbody", "tr", "td", "p", "div"}) {
            assertEquals(d1.select(css).size(), d2.select(css).size(), "selector count for " + css);
            assertEquals(d1.select(css).outerHtml(), d2.select(css).outerHtml(), "selector html for " + css);
        }
        assertEquals(d1.text(), d2.text());
    }

    @Test void cleanDoesNotModifyCallerDocumentOrSafelistAcrossCalls() {
        Safelist safelist = Safelist.none().addTags("p", "b");
        Document dirty = Jsoup.parseBodyFragment("<p onclick='x()'>a <b>b</b></p><font>c</font>");
        String original = dirty.body().html();
        Cleaner cleaner = new Cleaner(safelist);

        String c1 = cleaner.clean(dirty).body().html();
        String c2 = cleaner.clean(dirty).body().html();
        assertEquals(c1, c2);
        assertEquals(original, dirty.body().html()); // source document untouched
        assertEquals("<p>a <b>b</b></p>c", TextUtil.stripNewlines(c1));
    }
}

