import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.safety.Safelist;

public class Probe {
    static Safelist relaxed = Safelist.relaxed();
    static Safelist none = Safelist.none();

    static void t(String label, String input, Safelist s) {
        try {
            String c1 = Jsoup.clean(input, s);
            String c2 = Jsoup.clean(c1, s);
            System.out.println("== " + label);
            System.out.println("in : " + escape(input));
            System.out.println("c1 : " + escape(c1));
            if (!c1.equals(c2)) System.out.println("c2!: " + escape(c2) + "   <-- NOT IDEMPOTENT");
            // reparse check
            Document d = Jsoup.parseBodyFragment(c1);
            // ensure no script-ish nodes
            if (!d.select("script, style, iframe, object").isEmpty())
                System.out.println("!! dangerous element survived: " + d.select("script,style,iframe,object").outerHtml());
        } catch (Exception e) {
            System.out.println("== " + label + " THREW " + e);
        }
    }

    static String escape(String s) { return s.replace("\n", "\\n").replace("\t", "\\t").replace("\r", "\\r"); }

    public static void main(String[] args) {
        t("script with markup", "a<script><b>x</b>&amp;\"\\'</script>c", none);
        t("script unclosed", "<p>a</p><script>alert(1)", Safelist.none().addTags("p"));
        t("script unclosed then text", "before<script>alert(1)<p>hidden</p>", Safelist.none().addTags("p"));
        t("nested rejected", "<f1>t1<f2>t2<b>x</b>t3</f2>t4</f1>", Safelist.none().addTags("b"));
        t("broken table", "<table><tr><td>x</table>after", Safelist.none().addTags("table","tr","td","tbody"));
        t("table foster", "<table>loose<tr><td>x</td></tr></table>", Safelist.none().addTags("table","tr","td","tbody"));
        t("malformed attrs", "<p title=\"a'b\" class='x\"y' bad=`>t</p>", Safelist.none().addTags("p").addAttributes("p","title","class"));
        t("malformed attrs 2", "<p =foo><p a==b><p a='>t</p>", Safelist.none().addTags("p"));
        t("entity once", "<p>&amp;lt; &amp;amp; &lt;tag&gt;</p>", Safelist.none().addTags("p"));
        t("style rejected", "a<style>body{color:red}</style>b", none);
        t("style allowed", "a<style>a < b & \"q\"</style>b", Safelist.none().addTags("style"));
        t("script allowed", "x<script>if (a<b) alert(\"&amp;\")</script>y", Safelist.none().addTags("script"));
        t("textarea", "<textarea>  a <b> &amp; \n c</textarea>", Safelist.none().addTags("textarea"));
        t("pre", "<pre>  a\n\tb &lt; c</pre>", Safelist.none().addTags("pre"));
        t("iframe rejected", "a<iframe>content</iframe>b", none);
