        t("noembed", "a<noembed><b>x</b></noembed>b", Safelist.none().addTags("b"));
        t("noframes", "a<noframes><b>x</b></noframes>b", Safelist.none().addTags("b"));
        t("svg script", "<svg><script> a < b </script></svg>", Safelist.none().addTags("svg"));
        t("cdata in svg", "<svg><![CDATA[<b>x</b>]]></svg>", Safelist.none().addTags("svg"));
        t("comment", "a<!-- <b>x</b> -->b", Safelist.none().addTags("b"));
        t("nul bytes", "\0\0<p>a\0b</p>\0", Safelist.none().addTags("p"));
        t("empty", "", none);
