import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.safety.Safelist;
import java.util.*;

public class Fuzz {
    static String[] pieces = {
        "<p>a</p>", "<p>a", "<b>x</b>", "text", "  ", "\n", "<script>alert(1)</script>",
        "<script>if(a<b){}</script>", "<script>", "</script>", "<style>a{b:c}</style>",
        "<font>f</font>", "<div>d</div>", "<pre>  p\n q</pre>", "<code>c  c</code>",
        "<textarea>t\n t</textarea>", "<table><tr><td>x</td></tr></table>",
        "<table><td>bare</td>", "&amp;", "&lt;tag&gt;", "&amp;amp;", "<a href='javascript:1'>j</a>",
        "<a href='http://ok.com/'>ok</a>", "<p onclick='x()'>ev</p>", "<img src=x onerror=1>",
        "<unknown>u</unknown>", "<b>", "</b>", "<p title='a\"b'>q</p>", "<p a==b>m</p>",
        "<iframe>if</iframe>", "<noscript><b>ns</b></noscript>", "<svg><script>s</script></svg>",
        "<!-- c -->", "<?pi?>", "<![CDATA[cd]]>", "\0", "<h1>h</h1>", "C:\\\\path", "&bsol;",
        "<script>unclosed", "<style>unclosed", "<p", "<", ">", "< p>", "<p/>", "<br>"
    };
    static Safelist[] safelists = {
        Safelist.none(),
        Safelist.none().addTags("p","b","div","pre","code","textarea","table","tbody","tr","td","h1","br","a"),
        Safelist.basic(),
        Safelist.relaxed()
    };
    static int failures = 0;

    public static void main(String[] args) {
        Random r = new Random(42);
        for (int iter = 0; iter < 20000; iter++) {
            StringBuilder sb = new StringBuilder();
            int n = 1 + r.nextInt(5);
            for (int i = 0; i < n; i++) sb.append(pieces[r.nextInt(pieces.length)]);
            String input = sb.toString();
            Safelist s = safelists[r.nextInt(safelists.length)];
            check(input, s);
        }
        System.out.println("done, failures=" + failures);
    }

    static void check(String input, Safelist s) {
        String c1, c2, c3;
        try {
            c1 = Jsoup.clean(input, s);
            c2 = Jsoup.clean(c1, s);
            c3 = Jsoup.clean(c2, s);
        } catch (Exception e) {
            fail("threw " + e + " for input " + esc(input)); return;
