import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.safety.Safelist;

public class Pre {
    public static void main(String[] args) {
        Safelist s = Safelist.none().addTags("pre", "textarea", "listing", "p", "code");
        // initial newline in pre
        String in1 = "<pre>\nfoo</pre>";
        Document d1 = Jsoup.parseBodyFragment(in1);
        System.out.println("parse <pre>\\nfoo: text=[" + esc(d1.expectFirst("pre").text()) + "] wholeText=[" + esc(d1.expectFirst("pre").childNode(0) instanceof TextNode ? ((TextNode)d1.expectFirst("pre").childNode(0)).getWholeText() : "?") + "]");
        String h1 = d1.body().html();
        System.out.println("ser1=" + esc(h1));
        String h2 = Jsoup.parseBodyFragment(h1).body().html();
        System.out.println("ser2=" + esc(h2) + (h1.equals(h2) ? "" : "  <-- ROUNDTRIP UNSTABLE"));

        // double newline
        String in2 = "<pre>\n\nfoo</pre>";
        String x1 = Jsoup.parseBodyFragment(in2).body().html();
        String x2 = Jsoup.parseBodyFragment(x1).body().html();
        String x3 = Jsoup.parseBodyFragment(x2).body().html();
        System.out.println("pre \\n\\nfoo: x1=" + esc(x1) + " x2=" + esc(x2) + " x3=" + esc(x3));

        // textarea initial newline
        String t1 = Jsoup.parseBodyFragment("<textarea>\nabc</textarea>").body().html();
        String t2 = Jsoup.parseBodyFragment(t1).body().html();
        System.out.println("textarea: t1=" + esc(t1) + " t2=" + esc(t2));

        // through the cleaner
        String c1 = Jsoup.clean("<pre>\n\nkeep me</pre>", s);
        String c2 = Jsoup.clean(c1, s);
        System.out.println("clean pre: c1=" + esc(c1) + " c2=" + esc(c2) + (c1.equals(c2)?"":"  <-- NOT IDEMPOTENT"));
        Document dc = Jsoup.parseBodyFragment(c1);
        System.out.println("reparsed pre text=[" + esc(dc.expectFirst("pre").text()) + "]");

        String ct1 = Jsoup.clean("<textarea>\n\nkeep</textarea>", s);
        String ct2 = Jsoup.clean(ct1, s);
        System.out.println("clean textarea: c1=" + esc(ct1) + " c2=" + esc(ct2) + (ct1.equals(ct2)?"":"  <-- NOT IDEMPOTENT"));

        // CR variant
        String cr1 = Jsoup.clean("<pre>\r\nkeep</pre>", s);
        String cr2 = Jsoup.clean(cr1, s);
        System.out.println("clean pre CR: c1=" + esc(cr1) + " c2=" + esc(cr2));

        // void element with children (from parser oddity)
        Document v = Jsoup.parseBodyFragment("<br></br>text");
        System.out.println("void dom: " + esc(v.body().html()));

        // listing tag
        String l1 = Jsoup.parseBodyFragment("<listing>\nabc</listing>").body().html();
        String l2 = Jsoup.parseBodyFragment(l1).body().html();
        System.out.println("listing: l1=" + esc(l1) + " l2=" + esc(l2));
    }
    static String esc(String s) { return s.replace("\n","\\n").replace("\r","\\r").replace("\t","\\t"); }
}
