import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.safety.Safelist;

public class Trace {
    static void rep(String label, String h) {
        Safelist s = Safelist.none().addTags("p","b","div","br","h1");
        String c1 = Jsoup.clean(h, s);
        String c2 = Jsoup.clean(c1, s);
        System.out.println(label + ": " + (c1.equals(c2) ? "stable" : "UNSTABLE"));
        System.out.println("  c1=" + esc(c1));
        if (!c1.equals(c2)) System.out.println("  c2=" + esc(c2));
        // plain parse/serialize fixed-point?
        String s1 = Jsoup.parseBodyFragment(h).body().html();
        String s2 = Jsoup.parseBodyFragment(s1).body().html();
        System.out.println("  parseFP=" + (s1.equals(s2) ? "stable" : "UNSTABLE " + esc(s1) + " -> " + esc(s2)));
    }
    public static void main(String[] a) {
        rep("inline>block", "<b><p>q</p></b>");
        rep("text between blocks", "<p>One</p>Two<p>Four</p>");
        rep("hoisted text after block", "<p>a</p><unknown>u</unknown>");
        rep("br in inline", "<b>u<br></b>");
        rep("br in block", "<p>a<br>b</p>");
        rep("inline text + br", "<b>a<br>b</b>");
        rep("unknown only", "<unknown>u</unknown>");
        rep("b around div", "<b><div>d</div></b>");
        rep("a(allowed) img? n/a", "<b>x<br>y<br>z</b>");
    }
    static String esc(String s){return s.replace("\n","\\n").replace("\t","\\t");}
}
