140	                if (prev == null || !(prev instanceof TextNode) && shouldIndent(prev))
141	                    options |= Entities.TrimLeading;
142	            }
143	
144	            if (next == null || !(next instanceof TextNode) && shouldIndent(next)) {
145	                options |= Entities.TrimTrailing;
146	            } else { // trim trailing whitespace if the next non-empty TextNode has leading whitespace
147	                next = nextNonBlank(next);
148	                if (next instanceof TextNode && StringUtil.isWhitespace(next.nodeValue().codePointAt(0)))
