boolean shouldIndent(@Nullable Node node, boolean honorRoot) {
    if (node == null || honorRoot && node == root || preserveWhitespace || isBlankText(node))
        return false;

    // Synthetic indentation is only safe in a block formatting context, where it is trimmed back out of text
    // on the next pass. Inside an inline (formatting) element it is significant: a newline and padding would
    // survive a reparse as text (e.g. "<b>x<br>" prints a newline that re-parses attached to "x", so re-cleaning
    // the output would add and then keep a space). Block tags flagged InlineContainer (p, h1, td, ...) stay
    // indented as before.
    org.jsoup.nodes.Node rawParent = node.parentNode();
    if (rawParent instanceof Element) {
        Element parent = (Element) rawParent;
        if (!isBlockEl(parent) && !parent.tag().is(Tag.InlineContainer))
            return false;
    }

    if (isBlockEl(node))
        return true;

    Node prevSib = previousNonblank(node);

