boolean isBlockEl(@Nullable Node node) {
    if (node == null) return false;
    if (node instanceof Element) {
        Element el = (Element) node;
        if (el.nameIs("br")) return true; // give <br> a newline; actually an inline tag
        return el.isBlock() ||
            (!el.tag.isKnownTag() && (el.parentNode instanceof Document || hasChildBlocks(el))) ||
            // known transparent wrappers (a, ins, ...) are phrasing tags by content model, but when they
            // actually contain flow blocks they behave as block contexts: the surrounding blank text is
            // then trimmable, so indenting their children stays stable across reparse/re-clean
            (el.tag.isKnownTag() && el.tag().namespace().equals(org.jsoup.parser.Parser.NamespaceHtml)
                && StringUtil.in(el.normalName(), FlowWrappers) && hasChildBlocks(el));
    }

    return false;
}

// Inline (phrasing) tags whose content model is transparent and so may legitimately contain flow/block content
private static final String[] FlowWrappers = {"a", "ins", "del", "map", "object", "canvas", "audio", "video", "slot"};

