117	        int textTrim(TextNode node, int options) {
118	            if (!isBlockEl(node.parentNode)) return options; // don't trim inline, whitespace significant
119	            Node prev = node.previousSibling();
120	            Node next = node.nextSibling();
121	
122	            // if previous is not an inline element
123	            if (!(prev instanceof Element && !isBlockEl(prev))) {
