125	                // judged on its own layout, so the traversal root exemption does not apply: when serializing an
126	                // element's inner HTML that root is just the first of several siblings being printed, and treating
127	                // it specially would leave a leading newline on following text untrimmed, which would re-parse as
128	                // an extra space and make the output non-idempotent.
129	                if (prev == null || !(prev instanceof TextNode) && shouldIndent(prev, false))
130	                    options |= Entities.TrimLeading;
131	            }
