134	                options |= Entities.TrimTrailing;
135	            } else { // trim trailing whitespace if the next non-empty TextNode has leading whitespace
136	                next = nextNonBlank(next);
137	                if (next instanceof TextNode && StringUtil.isWhitespace(next.nodeValue().codePointAt(0)))
