package org.jsoup.nodes;

import org.jsoup.internal.QuietAppendable;
import org.jsoup.internal.StringUtil;
import org.jsoup.nodes.Document.OutputSettings;
import org.jsoup.parser.Tag;
import org.jsoup.select.NodeVisitor;
import org.jspecify.annotations.Nullable;

import static org.jsoup.nodes.Document.OutputSettings.Syntax.html;
import static org.jsoup.parser.Parser.NamespaceHtml;

/** Base Printer */
class Printer implements NodeVisitor {
    final Node root;
    final QuietAppendable accum;
    final OutputSettings settings;

    Printer(Node root, QuietAppendable accum, OutputSettings settings) {
        this.root = root;
        this.accum = accum;
        this.settings = settings;
    }

    void addHead(Element el, int depth) {
        el.outerHtmlHead(accum, settings);
        // The parser ignores a single LF immediately after a <pre>/<listing> start tag, so emit a duplicate:
        // otherwise the preserved leading newline would be lost when this output is re-parsed, making
        // serialize -> reparse -> serialize (and a second clean) drop one newline each time.
        if (settings.syntax() == html && el.tag().namespace().equals(NamespaceHtml)
            && StringUtil.in(el.normalName(), InitialNewlineTags)
            && el.firstChild() instanceof TextNode) {
            String text = ((TextNode) el.firstChild()).getWholeText();
            if (text.startsWith("\n"))
                accum.append('\n');
        }
    }

    private static final String[] InitialNewlineTags = {"pre", "listing"};

