/**
 Cleans the {@code bodyHtml} fragment and returns serialized output that is a fixed point: feeding the result
 back through {@link #clean(Document)} after an HTML re-parse yields the identical string.
 <p>
 A single clean can produce markup that the parser only normalizes once read back in -- e.g. nodes hoisted out of
 a rejected wrapper into a table context are foster-parented on reparse, and pretty-print indentation inside an
 inline element becomes significant text. Serializing those reparsed structures differs from the first output, so
 without settling them a second {@code clean} would move nodes or add whitespace. We iterate parse &rarr; clean
 &rarr; serialize until stable (which happens within a couple of passes), keeping the serialized result usable as
 stable HTML.
 @param bodyHtml input untrusted HTML (body fragment)
 @param baseUri  base URI applied when parsing (both initially and on re-parse)
 @param outputSettings output settings to serialize the result with
 @return cleaned, reparse-stable body HTML
 */
String stableBodyHtml(String bodyHtml, String baseUri, Document.OutputSettings outputSettings) {
    Document first = clean(Parser.parseBodyFragment(bodyHtml, baseUri));
    String html = serialize(first, outputSettings);

    for (int pass = 0; pass < MaxStablePasses; pass++) {
        Document reparsed = Parser.parseBodyFragment(html, baseUri);
        Document recleaned = clean(reparsed);
        String next = serialize(recleaned, outputSettings);
        if (next.equals(html)) return next;
        html = next;
    }
    return html;
}

private static String serialize(Document clean, Document.OutputSettings outputSettings) {
    clean.outputSettings(outputSettings);
    return clean.body().html();
}

// Bound on the number of settle passes; parse/clean/serialize converges to a fixed point well within this. The
// loop is guarded anyway so an unexpected non-converging input still returns its last serialized form.
private static final int MaxStablePasses = 10;

