import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.safety.Safelist;
import java.util.*;

public class Equiv {
    static String[] pieces = {
        "<p>a</p>", "<p>a", "<b>x</b>", "text", "  ", "\n", "<script>alert(1)</script>",
        "<script>if(a<b){}</script>", "</script>", "<style>a{b:c}</style>",
        "<font>f</font>", "<div>d</div>", "<pre>  p\n q</pre>", "<code>c  c</code>",
        "<textarea>t\n t</textarea>", "<table><tr><td>x</td></tr></table>",
        "<table><td>bare</td>", "&amp;", "&lt;tag&gt;", "&amp;amp;", "<a href='javascript:1'>j</a>",
        "<a href='http://ok.com/'>ok</a>", "<p onclick='x()'>ev</p>", "<img src=x onerror=1>",
        "<unknown>u</unknown>", "<b>", "</b>", "<p title='a\"b'>q</p>", "<p a==b>m</p>",
        "<iframe>if</iframe>", "<noscript><b>ns</b></noscript>", "<svg><script>s</script></svg>",
        "<!-- c -->", "<h1>h</h1>", "C:\\\\path", "&bsol;",
        "<script>unclosed", "<style>unclosed", "<br>", "<ins><p>One</p></ins>", "<a><div>dv</div></a>",
        "<table><td>x</td><noscript><b>ns</b></noscript></table>", "tail", "pre", "<i>i</i>"
    };
    static Safelist[] safelists = {
        Safelist.none(),
        Safelist.none().addTags("p","b","i","div","pre","code","textarea","table","tbody","tr","td","h1","h2","br","a","ins","del","span","font"),
        Safelist.basic(),
        Safelist.relaxed()
    };
    static int failures = 0;

    // single-pass clean(Document), not the stabilized string path
    static String single(String html, Safelist s) {
        return new Cleaner(s).clean(Jsoup.parseBodyFragment(html)).body().html();
    }
    static String sig(Document d) {
        StringBuilder sb = new StringBuilder();
        for (Element el : d.body().getAllElements()) {
            if (el == d.body()) continue;
            sb.append("<").append(el.normalName()).append(">");
            for (Attribute a : el.attributes()) sb.append("@").append(a.getKey()).append("=").append(a.getValue());
        }
        // visible text with whitespace normalized like text()
        sb.append("|").append(d.body().text());
        return sb.toString();
    }
    static String order(Document d) {
        StringBuilder sb = new StringBuilder();
        NodeTraversor.traverse(new NodeVisitor() {
            public void head(Node n, int depth) {
                if (n instanceof Element) sb.append("<").append(((Element)n).normalName()).append(">");
                else if (n instanceof TextNode) sb.append(((TextNode)n).getWholeText().replaceAll("\\s+",""));
            }
            public void tail(Node n, int depth) {}
        }, d.body());
        return sb.toString();
    }

    public static void main(String[] args) {
        Random r = new Random(7);
        for (int iter = 0; iter < 40000; iter++) {
            StringBuilder sb = new StringBuilder();
            int n = 1 + r.nextInt(6);
            for (int i = 0; i < n; i++) sb.append(pieces[r.nextInt(pieces.length)]);
            String input = sb.toString();
            Safelist s = safelists[r.nextInt(safelists.length)];

            String stable = Jsoup.clean(input, s);
            // invariants on the stable output
            if (!stable.equals(Jsoup.clean(stable, s))) fail("not idempotent: " + esc(input) + " -> " + esc(stable) + " -> " + esc(Jsoup.clean(stable, s)));

            Document ds = Jsoup.parseBodyFragment(stable);
            Document d1 = Jsoup.parseBodyFragment(single(input, s));

            // element+attr signature must be identical between single pass and settled (no safe node/attr lost)
            if (!sig(ds).equals(sig(d1)))
                fail("sig differs:\n in=" + esc(input) + "\n single=" + esc(single(input,s)) + "\n stable=" + esc(stable) + "\n sig1=" + sig(d1) + "\n sigS=" + sig(ds));

            // document order of tags and non-ws text identical
            if (!order(ds).equals(order(d1)))
                fail("order differs:\n in=" + esc(input) + "\n single=" + esc(single(input,s)) + "\n stable=" + esc(stable) + "\n o1=" + order(d1) + "\n oS=" + order(ds));

            // safety
            for (Element el : ds.body().getAllElements()) {
                String tag = el.normalName();
                if (!s.isSafeTag(tag) && !tag.equals("html") && !tag.equals("head") && !tag.equals("body"))
                    fail("unsafe tag <" + tag + "> in " + esc(stable));
                for (Attribute a : el.attributes())
                    if (a.getKey().toLowerCase().startsWith("on")) fail("event attr in " + esc(stable));
            }
            if (ds.body().html().toLowerCase().contains("javascript:")) fail("javascript: in " + esc(stable));
        }
        System.out.println("done, failures=" + failures);
    }
    static void fail(String m){ System.out.println("FAIL: " + m); if(++failures>10) System.exit(1); }
    static String esc(String s){return s.replace("\n","\\n").replace("\t","\\t").replace("\r","\\r");}
}
EOF
