import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.safety.*;
import java.util.*;

public class Passes {
    static int count(String html, Safelist s) {
        Cleaner c = new Cleaner(s);
        Document.OutputSettings st = new Document.OutputSettings();
        String out = c.clean(Jsoup.parseBodyFragment(html)).body().html();
        int passes = 0;
        for (int i = 0; i < 10; i++) {
            passes++;
            Document d = c.clean(Jsoup.parseBodyFragment(out));
            d.outputSettings(st);
            String next = d.body().html();
            if (next.equals(out)) return passes;
            out = next;
        }
        return -1; // did not converge
    }
    public static void main(String[] a) {
        String[] fixed = {
            "<p>a</p><p>b</p>", "hello <b>b</b>", "<b><p>q</p></b>",
            "<table><td>bare</td><noscript><b>ns</b></noscript></table>",
            "<b>x<br>y</b>", "<a><div>One</div></a>", "<pre>\n\nx</pre>",
