// table elements that only accept specific table-model children; other content is foster-parented on reparse
private static boolean isTableContainer(Element el) {
    return el.nameIs("table") || el.nameIs("tbody") || el.nameIs("thead") || el.nameIs("tfoot") || el.nameIs("tr");
