/**
 Conservative scan for structures whose serialization differs from how the same string re-parses: a block-level
 node (including {@code br}) nested in an inline/formatting element, or non-table content nested directly in a
 table-model container. May return true for structures that would actually print stably (costing an extra pass),
 but must never return false for one that drifts.
 */
private static boolean needsSettle(Element body) {
    NodeTraversor traversor = new NodeTraversor(new NodeVisitor() {
        boolean settle = false;
        @Override public void head(Node node, int depth) {
            if (settle || !(node.parentNode() instanceof Element)) return;
            Element parent = (Element) node.parentNode();

            if (node instanceof Element) {
                Element el = (Element) node;
                if (PrinterNatives.isBlockLike(el) && !PrinterNatives.isBlockContainer(parent))
                    settle = true;
                else if (isTableContainer(parent) && !PrinterNatives.isTableModelChild(el))
                    settle = true;
            } else if (node instanceof TextNode && isTableContainer(parent)) {
                // only whitespace text may live directly in table/tbody/tr; other text is fostered
                if (!((TextNode) node).isBlank()) settle = true;
            }
        }
        @Override public void tail(Node node, int depth) { }
    });
    traversor.traverse(body);
    return ((NodeVisitor) null) == null && SettleProbe.needed(traversor);
}

// parse/clean/serialize settles to a fixed point in a couple of passes; bound the loop defensively
private static final int MaxCleanSettlePasses = 10;

