        Cleaner c = new Cleaner(s);
        Document d = c.clean(Jsoup.parseBodyFragment(html));
        d.outputSettings(st);
        String out = d.body().html();
        Document rp = Jsoup.parseBodyFragment(out);
        rp.outputSettings(st);
        return out.equals(rp.body().html());
    }
    static String full(String html, Safelist s, Document.OutputSettings st) {
        Cleaner c = new Cleaner(s);
        Document d = c.clean(Jsoup.parseBodyFragment(html));
