import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.parser.Tag;
import org.jsoup.safety.*;
import java.util.*;

public class Detect {
    static final Set<String> TABLE_CTX = new HashSet<>(Arrays.asList("table","tbody","thead","tfoot","tr"));
    static boolean tableChildOk(String parent, String child) {
        switch (parent) {
            case "table": return child.equals("caption")||child.equals("colgroup")||child.equals("col")
                ||child.equals("tbody")||child.equals("thead")||child.equals("tfoot")||child.equals("tr")
                ||child.equals("script")||child.equals("template");
            case "tbody": case "thead": case "tfoot":
                return child.equals("tr")||child.equals("script")||child.equals("template");
            case "tr": return child.equals("td")||child.equals("th")||child.equals("script")||child.equals("template");
            default: return true;
        }
    }
    static boolean hasChildBlock(Element el) {
        int i=0;
        for (Element c = el.firstElementChild(); c!=null && i<5; c=c.nextElementSibling(),i++)
            if (c.isBlock() || !c.tag().isKnownTag()) return true;
        return false;
    }
    static boolean blockLike(Element el) {
        if (el.nameIs("br")) return true;
        if (el.isBlock()) return true;
        if (!el.tag().isKnownTag()) return el.parentNode() instanceof Document || hasChildBlock(el);
        return false;
    }
    static boolean blockContext(Element p) {
        if (p instanceof Document) return true;
        if (p.nameIs("br")) return false;
        if (p.isBlock()) return true;
        if (!p.tag().isKnownTag()) return p.parentNode() instanceof Document || hasChildBlock(p);
        return false;
    }
    static boolean domNeedsSettle(Element body) {
        for (Node n : new ArrayList<>(body.getAllElements())) {
            if (!(n instanceof Element)) continue;
            Element el = (Element) n;
            Node pn = el.parentNode();
            if (pn instanceof Element) {
                Element p = (Element) pn;
                String ns = el.tag().namespace();
                boolean html = ns.equals("http://www.w3.org/1999/xhtml");
                String pn2 = p.normalName();
                if (TABLE_CTX.contains(pn2) && html && !tableChildOk(pn2, el.normalName())) return true;
                if (html && blockLike(el) && !blockContext(p) && !p.tag().is(Tag.InlineContainer)) {
                    // over-flag possible; acceptable
                    return true;
                }
            }
        }
        // non-blank text directly in table/tbody/thead/tfoot/tr
        boolean[] found = {false};
        NodeTraversor.traverse(new NodeVisitor() {
            public void head(Node node, int depth) {
                if (found[0]) return;
                if (node instanceof TextNode && node.parentNode() instanceof Element) {
                    Element p = (Element) node.parentNode();
                    String pn = p.normalName();
                    if (TABLE_CTX.contains(pn) && !((TextNode)node).isBlank()) found[0]=true;
