            "<table><tr><td>x</td></tr></table>","<table><td>bare</td>","&amp;","&lt;tag&gt;","&amp;amp;",
            "<a href='javascript:1'>j</a>","<a href='http://ok.com/'>ok</a>","<p onclick='x()'>ev</p>",
            "<img src=x onerror=1>","<unknown>u</unknown>","<b>","</b>","<p title='a\"b'>q</p>","<p a==b>m</p>",
            "<iframe>if</iframe>","<noscript><b>ns</b></noscript>","<svg><script>s</script></svg>","<!-- c -->",
            "<h1>h</h1>","C:\\\\p","&bsol;","<script>unclosed","<style>unclosed","<br>","<ins><p>One</p></ins>",
            "<a><div>dv</div></a>","<table><td>x</td><noscript><b>ns</b></noscript></table>","tail","pre","<i>i</i>",
            "<s><p>One</p></s>","<svg><g></g></svg>","<math><mi>x</mi></math>","<thead></thead>","<tfoot><tr><th>h</th></tr></tfoot>"};
        Safelist[] sl = {Safelist.none(),
            Safelist.none().addTags("p","b","i","s","div","pre","code","textarea","table","tbody","thead","tfoot","tr","td","th","h1","br","a","ins","del","span","font","svg","g","math","mi","img","caption","colgroup"),
            Safelist.basic(), Safelist.relaxed()};
        Document.OutputSettings st = new Document.OutputSettings();
        Random r = new Random(123);
        int falseNeg=0, falsePos=0, agree=0, n=0;
        for (int it=0; it<100000; it++) {
            StringBuilder sb=new StringBuilder(); int cnt=1+r.nextInt(6);
            for (int i=0;i<cnt;i++) sb.append(pieces[r.nextInt(pieces.length)]);
            String html=sb.toString(); Safelist s=sl[r.nextInt(sl.length)];
            boolean cheap = cheapStable(html,s,st);
            boolean dom = domSays(html,s);
            n++;
            if (!cheap && !dom) { falseNeg++; if(falseNeg<=8) System.out.println("FALSE NEG: in="+html.replace("\n","\\n")); }
            if (cheap && dom) falsePos++;
            else agree++;
        }
        System.out.println("n="+n+" falseNeg(missed drift)="+falseNeg+" falsePos(extra settle)="+falsePos);
    }
}
