/**
 Serializes a cleaned fragment and re-runs parse &rarr; clean &rarr; serialize until the string is a fixed point,
 so that cleaning the returned HTML again yields the identical string. One pass can leave markup that the parser
 only normalizes when read back (nodes foster-parented out of a table context, or pretty-print indentation inside
 an inline element becoming significant text); settling those here keeps the output stable HTML without changing
 how a Document is cleaned directly via {@link Cleaner#clean(Document)}.
 */
private static String stableCleanBodyHtml(String bodyHtml, String baseUri, Cleaner cleaner, Document.OutputSettings settings) {
    String html = serializeClean(cleaner.clean(parseBodyFragment(bodyHtml, baseUri)), settings);
    for (int pass = 0; pass < MaxCleanSettlePasses; pass++) {
        String next = serializeClean(cleaner.clean(parseBodyFragment(html, baseUri)), settings);
        if (next.equals(html)) return next;
        html = next;
    }
    return html;
}

private static String serializeClean(Document clean, Document.OutputSettings settings) {
    clean.outputSettings(settings.clone());
    return clean.body().html();
}

// parse/clean/serialize settles to a fixed point in a couple of passes; bound the loop defensively
private static final int MaxCleanSettlePasses = 10;

