import org.jsoup.safety.Safelist;

public class Settings {
    static void check(String label, String html, Safelist s, Document.OutputSettings st) {
        String c1 = Jsoup.clean(html, "https://example.com/a/b/", s, st);
        String c2 = Jsoup.clean(c1, "https://example.com/a/b/", s, st);
        System.out.println(label + ": idem=" + c1.equals(c2));
        if (!c1.equals(c2)) { System.out.println(" c1=" + esc(c1)); System.out.println(" c2=" + esc(c2)); }
        else System.out.println(" -> " + esc(c1));
        // reparse safe
        Document d = Jsoup.parseBodyFragment(c1);
        if (!d.select("script,style,iframe").isEmpty()) System.out.println("  !! unsafe");
    }
    public static void main(String[] a) {
        Safelist s = Safelist.none().addTags("p","b","br","div","a","table","tbody","tr","td","pre");
        String hard = "<b><p>q</p></b><table><td>x</td><noscript><b>ns</b></noscript></table><a href='/rel/'>r</a><pre>\n\nk</pre>";

        check("default pretty", hard, s, new Document.OutputSettings());
        check("pretty off", hard, s, new Document.OutputSettings().prettyPrint(false));
        check("xml syntax", hard, s, new Document.OutputSettings().syntax(Document.OutputSettings.Syntax.xml));
        check("xhtml escape", hard, s, new Document.OutputSettings().escapeMode(Entities.EscapeMode.xhtml));
        check("indent 4", hard, s, new Document.OutputSettings().indentAmount(4));
        check("charset ascii", "café <p>naïve &amp; b</p>", s, new Document.OutputSettings().charset(java.nio.charset.Charset.forName("ascii")));

        // cross-safelist pollution
        Safelist s1 = Safelist.none().addTags("p");
        Safelist s2 = Safelist.none().addTags("b");
        String a1 = Jsoup.clean("<p>x</p><b>y</b>", s1);
        String a2 = Jsoup.clean("<p>x</p><b>y</b>", s2);
        String a3 = Jsoup.clean("<p>x</p><b>y</b>", s1);
        System.out.println("no cross-pollution: " + a1.equals(a3) + "  s1=" + esc(a1) + " s2=" + esc(a2));

        // caller document untouched
        Document doc = Jsoup.parseBodyFragment("<p onclick='x()'>a</p><script>bad()</script>");
        String before = doc.body().html();
        new Cleaner(s).clean(doc);
        System.out.println("caller doc untouched: " + before.equals(doc.body().html()));

        // base uri / relative link stability through settle
        Safelist basic = Safelist.basic().preserveRelativeLinks(true);
        String r1 = Jsoup.clean("<a href='../other'>x</a><b><p>p</p></b>", "https://example.com/a/b/", basic);
        String r2 = Jsoup.clean(r1, "https://example.com/a/b/", basic);
        System.out.println("relative+settle idem=" + r1.equals(r2) + " -> " + esc(r1));
    }
    static String esc(String s){return s.replace("\n","\\n").replace("\t","\\t").replace("\r","\\r");}
}
