        Safelist p = Safelist.none().addTags("p");
        // rejected script: its char-data must not become nodes/attrs; surrounding text retained in order
        expectText("script markup literals",
            "a<script><b>x</b> &amp; \" \\ ' </script>b", none, "a <b>x</b> & \" \\ ' b".replace("&amp;","&"));
        // note: script content is Data, discarded entirely by cleaner; so expected is "ab" only
        expectText("script data discarded", "a<script><b>x</b>&amp;\"\\'</script>b", none, "ab");
        expectText("style data discarded", "a<style>b{color:red}</style>b", none, "ab");
        // event attr removed, text kept
        expectText("event attr", "<p onclick='alert(1)'>hi</p>", p, "hi");
        // entity spelled text survives literally (decoded exactly once by parser)
        expectText("entity once", "<p>&amp;amp; &lt;tag&gt; &quot; &#92;</p>", p, "&amp; <tag> \" \\");
        // backslash literal
        expectText("backslash", "<p>C:\\x\\y &bsol; z</p>", p, "C:\\x\\y \\ z");
        // quotes/angle brackets as literal text
        expectText("brackets quotes", "<p>1 < 2 && 3 > 0 \"q\" 'r'</p>", p, "1 < 2 && 3 > 0 \"q\" 'r'");
        // script-looking text that is actually plain text (escaped by user as entities)
        expectText("text that looks like tag", "<p>&lt;script&gt;alert(1)&lt;/script&gt;</p>", p, "<script>alert(1)</script>");
        // unclosed danger then safe block
        expectText("unclosed script", "before<script>alert(1)<p>hidden</p>", p, "before");
        // nested rejected wrappers keep order
        expectText("nested", "<x>1<y>2<p>P</p>3</y>4</x>", p, "12P34");
        // allowed element inside rejected script-ish wrapper via noscript
        expectText("noscript", "a<noscript><b>x</b></noscript>b", Safelist.none().addTags("b"), "axb");
        System.out.println(fail==0?"ALL GOOD":(fail+" FAILURES"));
    }
}
