import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.safety.*;
import java.util.*;

public class Conv {
    static Cleaner c; static Document.OutputSettings st;
    static String settle(String html) {
        String out = c.clean(Jsoup.parseBodyFragment(html)).body().html();
        for (int i=0;i<10;i++) {
            String n = c.clean(Jsoup.parseBodyFragment(out)).body().html();
            if (n.equals(out)) return out;
            out = n;
        }
        return null;
    }
    public static void main(String[] a) {
        Safelist s = Safelist.none().addTags("p","b","i","div","table","tbody","thead","tfoot","tr","td","th","caption","colgroup","col","br","a","ins","span","h1","pre","script");
        c = new Cleaner(s); st = new Document.OutputSettings();
        String[] atoms = {"<p>a</p>","<b>","</b>","<div>","</div>","<table>","</table>","<tr>","</tr>","<td>","</td>",
            "<thead>","</thead>","<caption>","</caption>","<br>","<ins>","</ins>","<a>","</a>","<h1>h</h1>","x","\n"," ","<span>","</span>"};
        Random r = new Random(99);
        int nonConv=0, maxPass=-1, n=300000;
        for (int it=0; it<n; it++) {
            StringBuilder sb=new StringBuilder(); int k=1+r.nextInt(10);
            for (int i=0;i<k;i++) sb.append(atoms[r.nextInt(atoms.length)]);
            String in=sb.toString();
            // measure passes
            String out=c.clean(Jsoup.parseBodyFragment(in)).body().html(); int pass=0; boolean conv=false;
            for (int i=0;i<10;i++){pass++; String n2=c.clean(Jsoup.parseBodyFragment(out)).body().html(); if(n2.equals(out)){conv=true;break;} out=n2;}
            if(!conv){nonConv++; if(nonConv<=5)System.out.println("NONCONV: "+in);}
            if(pass>maxPass)maxPass=pass;
        }
        // deeply nested
        for (int depth : new int[]{5,20,100,500}) {
            StringBuilder sb=new StringBuilder();
            for(int i=0;i<depth;i++) sb.append("<b><table><tr><td>");
            sb.append("CORE");
            for(int i=0;i<depth;i++) sb.append("</td></tr></table></b>");
            String r1 = Jsoup.clean(sb.toString(), s);
            String r2 = Jsoup.clean(r1, s);
            System.out.println("depth "+depth+" idem="+r1.equals(r2));
        }
        System.out.println("n="+n+" nonConverged="+nonConv+" maxPasses="+maxPass);
    }
}
