            "<noscript><b>ns</b></noscript>","<br>","<ins><p>p</p></ins>","<a><div>dv</div></a>","<i>i</i>","</table>",
            "<tbody>","</tbody>","<tr>","<td>","</td>","</tr>","<s><p>One</p></s>","<script>unclosed","<caption>c</caption>"};
        Safelist[] sl = {Safelist.none(),
            Safelist.none().addTags("p","b","i","s","div","table","tbody","thead","tfoot","tr","td","th","br","a","ins","span","caption","colgroup","h1"),
            Safelist.basic(), Safelist.relaxed()};
        Random r = new Random(5);
        int bad=0;
        for (int it=0; it<100000; it++) {
            StringBuilder sb=new StringBuilder(); int n=1+r.nextInt(7);
            for(int i=0;i<n;i++) sb.append(pieces[r.nextInt(pieces.length)]);
            String in=sb.toString(); Safelist s=sl[r.nextInt(sl.length)];
            String c1 = Jsoup.clean(in, s); // default pretty
            String k1 = Jsoup.clean(in, "", s, new Document.OutputSettings().prettyPrint(false));
            String k2 = Jsoup.clean(k1, "", s, new Document.OutputSettings().prettyPrint(false));
            if (!k1.equals(k2)) { bad++; if(bad<=8) System.out.println("COMPACT DRIFT in="+in.replace("\n","\\n")+"\n k1="+k1+"\n k2="+k2); }
            // safety
            Document d = Jsoup.parseBodyFragment(k1);
            if (d.body().html().toLowerCase().contains("javascript:") || !d.select("script,style").isEmpty()) {bad++; System.out.println("UNSAFE "+in);}
        }
        System.out.println("compact bad="+bad);
    }
}
